   <a class="skip-link" href="#support-form">Skip to contact form</a>

   <main id="main-content">
     <section class="support-card" aria-labelledby="page-title">
       <header class="support-card__header">
         <h1 id="page-title">Contact Support</h1>
         <p class="lede">Send us your details and we'll get back to you as soon as we can.</p>
